head.script:
// 전역 변수
scwin.CURRENT_PROJECT_ID = "";
scwin.CURRENT_USER_ID = "";
scwin.CURRENT_USER_GROUP_ID = "";

// 페이징 정보
scwin.successPageInfo = { currentPage: 1, pageSize: 10, totalCount: 0, data: [] };
scwin.failPageInfo = { currentPage: 1, pageSize: 10, totalCount: 0, data: [] };
scwin.globalElData = null;

/**
 * 페이지 로드 시 초기화
 */
scwin.onpageload = function() {
    console.log("단위테스트 목록 페이지 로드");

    // 초기화
    scwin.initializeData();

    // 사용자 정보 가져오기
    scwin.getCurrentUserInfo();

    // 부모 창에서 프로젝트 ID 가져오기
    scwin.getProjectIdFromParent();

    // 권한에 따른 UI 조정
    setTimeout(function() {
        scwin.adjustUIByPermission();
    }, 200);

    // 개발업무 연동 파라미터 처리
    scwin.handleTaskIdParam();

    console.log("페이지 로드 완료");
};

/**
 * 데이터 초기화
 */
scwin.initializeData = function() {
    console.log("데이터 초기화 시작");

    // 검색 조건 초기화
    dmp_search.set("pageIndex", "1");
    dmp_search.set("pageSize", "1000");

    // 페이징 정보 초기화
    scwin.successPageInfo = { currentPage: 1, pageSize: 10, totalCount: 0, data: [] };
    scwin.failPageInfo = { currentPage: 1, pageSize: 10, totalCount: 0, data: [] };

    console.log("데이터 초기화 완료");
};

/**
 * 현재 사용자 정보 가져오기
 */
scwin.getCurrentUserInfo = function() {
    try {
        var parentWindow = $p.getParentWindow();
        if (parentWindow) {
            var headerFrame = parentWindow.$p.getComponentById("pg_header");
            if (headerFrame && headerFrame.getWindow && headerFrame.getWindow().scwin) {
                var headerScwin = headerFrame.getWindow().scwin;
                var headerDoc = headerFrame.getWindow();

                scwin.CURRENT_USER_ID = headerScwin.USER_ID || "1";

                try {
                    var selectBox = headerDoc.$p.getComponentById("selectBoxProjectName");
                    var selectedPjtId = selectBox ? selectBox.getValue() : null;

                    if (selectedPjtId && headerDoc.dlt_projectName) {
                        var grpIdResult = headerDoc.dlt_projectName.getMatchedColumnData("pjtId", selectedPjtId, "grpId");
                        scwin.CURRENT_USER_GROUP_ID = Array.isArray(grpIdResult) ? grpIdResult[0] : grpIdResult;
                    } else {
                        scwin.CURRENT_USER_GROUP_ID = "2";
                    }
                } catch (projectError) {
                    console.error("프로젝트 정보 가져오기 실패:", projectError);
                    scwin.CURRENT_USER_GROUP_ID = "2";
                }

                console.log("사용자 정보:", {
                    userId: scwin.CURRENT_USER_ID,
                    groupId: scwin.CURRENT_USER_GROUP_ID,
                    isPM: scwin.CURRENT_USER_GROUP_ID === "1"
                });

                return true;
            }
        }

        scwin.CURRENT_USER_ID = "1";
        scwin.CURRENT_USER_GROUP_ID = "2";
        console.log("기본값으로 사용자 정보 설정");
        return false;

    } catch (e) {
        console.error("사용자 정보 가져오기 실패:", e);
        scwin.CURRENT_USER_ID = "1";
        scwin.CURRENT_USER_GROUP_ID = "2";
        return false;
    }
};

/**
 * PM 권한 여부 확인
 */
scwin.isPM = function() {
    var groupId = scwin.CURRENT_USER_GROUP_ID;
    if (Array.isArray(groupId)) {
        groupId = groupId[0];
    }
    return String(groupId) === "1";
};

/**
 * 부모 창에서 프로젝트 ID 가져오기
 */
scwin.getProjectIdFromParent = function() {
    try {
        var parentWindow = $p.getParentWindow();
        if (parentWindow && parentWindow.scwin && parentWindow.scwin.SEL_PJT_ID) {
            scwin.CURRENT_PROJECT_ID = parentWindow.scwin.SEL_PJT_ID;
            console.log("현재 선택된 프로젝트 ID:", scwin.CURRENT_PROJECT_ID);

            if (scwin.CURRENT_PROJECT_ID && scwin.CURRENT_PROJECT_ID !== "") {
                scwin.searchUnitTestsByProject();
                scwin.loadStatisticsByProject();
            }
        } else {
            console.log("부모 창에서 프로젝트 ID를 찾을 수 없습니다.");
        }
    } catch (e) {
        console.error("부모 창에서 프로젝트 ID 가져오기 실패:", e);
    }
};

/**
 * 개발업무 연동 파라미터 처리
 */
scwin.handleTaskIdParam = function() {
    try {
        var developParam = $p.getParameter("tabData");
        if (developParam && developParam.selectedTaskId) {
            console.log("개발업무에서 전달받은 업무ID:", developParam.selectedTaskId);

            if (developParam.openRegisterPopup) { 
                scwin.openTestRegisterPopupWithTask(developParam.selectedTaskId, developParam.selectedTaskName || "");
            } else { 
                scwin.openTestViewPopupWithTask(developParam.selectedTaskId, developParam.selectedTaskName || "");
            } 
        }
    } catch (e) {
        console.log("개발 업무ID 파라미터 처리 생략");
    }
};

/**
 * 권한에 따른 UI 조정
 */
scwin.adjustUIByPermission = function() {
    try {
        if (scwin.isPM()) {
            console.log("PM 권한: 모든 기능 사용 가능");
            scwin.enableAllSearchFields();
        } else {
            console.log("일반 사용자 권한: 제한된 기능");
            scwin.restrictAssigneeSearch();
        }
    } catch (e) {
        console.error("UI 권한 조정 실패:", e);
    }
};

/**
 * 모든 검색 필드 활성화
 */
scwin.enableAllSearchFields = function() {
    try {
        var searchFields = [
            "inp_searchAssignee", 
            "sel_searchTestStatus", 
            "inp_searchTestCaseName", 
            "inp_searchTestTarget",
            "sel_searchPriority",
            "sel_searchTestType"
        ];

        searchFields.forEach(function(fieldId) {
            var field = $p.getComponentById(fieldId);
            if (field && field.setReadOnly) {
                field.setReadOnly(false);
            }
        });

        console.log("PM 권한: 모든 검색 필드 활성화 완료");
    } catch (e) {
        console.error("검색 필드 활성화 실패:", e);
    }
};

/**
 * 담당자 검색 제한
 */
scwin.restrictAssigneeSearch = function() {
    try {
        var assigneeField = $p.getComponentById("inp_searchAssignee");
        if (assigneeField) {
            assigneeField.setValue(scwin.CURRENT_USER_ID);
            assigneeField.setReadOnly(true);
            assigneeField.setStyle("background-color: #f8f9fa; color: #6c757d;");
        }
    } catch (e) {
        console.error("담당자 검색 제한 실패:", e);
    }
};

/**
 * 조회 버튼 클릭
 */
scwin.btn_search_onclick = function(e) {
    console.log("조회 버튼 클릭");

    if (scwin.CURRENT_PROJECT_ID && scwin.CURRENT_PROJECT_ID !== "") {
        scwin.searchUnitTestsByProject();
    } else {
        scwin.searchUnitTests();
    }
};

/**
 * 등록 버튼 클릭
 */
scwin.btn_register_onclick = function(e) {
    console.log("등록 버튼 클릭");

    // 현재 사용자 정보 가져오기
    var currentUserId = scwin.CURRENT_USER_ID || "1";
    var currentUserName = scwin.getCurrentUserName();
    var currentProjectId = scwin.CURRENT_PROJECT_ID || "";

    console.log("팝업에 전달할 사용자 정보:");
    console.log("- USER_ID:", currentUserId);
    console.log("- USER_NAME:", currentUserName);
    console.log("- PROJECT_ID:", currentProjectId);

    // 사용자 정보를 포함한 데이터 준비
    var userData = {
        mode: "new",
        currentUserId: currentUserId,
        currentUserName: currentUserName,
        currentProjectId: currentProjectId,
        pjtId: currentProjectId
    };

    // 팝업 데이터 준비
    var taskData = {
        mode: "new",
        taskId: "",
        taskName: "",
        pjtId: currentProjectId,
        currentUserId: currentUserId,
        currentUserName: currentUserName
    };

    var jsnPopupData = {
        "type": "json",
        "name": "taskData",
        "data": taskData
    };

    var options = {
        id: "unit_test_popup",
        type: "wframePopup",
        width: "1400px",
        height: "900px",
        top: "50px",
        left: "100px",
        popupName: "단위테스트 케이스 등록",
        modal: true,
        closeAction: "scwin.testPopup_closeAction",
        dataObject: jsnPopupData
    };

    console.log("팝업 열기 - 사용자 정보 포함:", taskData);
    $p.openPopup("/InsWebApp/ui/test/UnitTestPopup.xml", options);
};


scwin.getCurrentUserName = function() {
    try {
        var parentWindow = $p.getParentWindow();
        if (parentWindow) {
            // 메인 페이지의 헤더 프레임에서 사용자 이름 가져오기
            var headerFrame = parentWindow.$p.getComponentById("pg_header");
            if (headerFrame && headerFrame.getWindow && headerFrame.getWindow().scwin) {
                var headerScwin = headerFrame.getWindow().scwin;

                // Test.xml과 동일한 방식
                if (headerScwin.USER_NAME) {
                    console.log("헤더에서 사용자 이름 가져옴:", headerScwin.USER_NAME);
                    return headerScwin.USER_NAME;
                }

                // 추가 시도: 다른 가능한 속성들
                var possibleProps = ['userName', 'currentUserName', 'userNm'];
                for (var i = 0; i < possibleProps.length; i++) {
                    var prop = possibleProps[i];
                    if (headerScwin[prop] && headerScwin[prop] !== "사용자") {
                        console.log("헤더에서 " + prop + " 가져옴:", headerScwin[prop]);
                        return headerScwin[prop];
                    }
                }

                console.log("헤더 scwin의 모든 속성들:");
                for (var prop in headerScwin) {
                    if (typeof headerScwin[prop] === 'string' && headerScwin[prop].length > 0) {
                        console.log("- " + prop + ":", headerScwin[prop]);

                        // 사용자 이름일 가능성이 있는 속성들 체크
                        if ((prop.toLowerCase().includes('user') && prop.toLowerCase().includes('name')) ||
                            prop === 'USER_NAME' || prop === 'userName' || prop === 'currentUserName') {
                            if (headerScwin[prop] !== "사용자" && headerScwin[prop] !== "현재 사용자") {
                                console.log("사용자 이름 후보 발견:", prop, "=", headerScwin[prop]);
                                return headerScwin[prop];
                            }
                        }
                    }
                }
            }
        }

        // 헤더에서 가져오지 못한 경우 기본값
        console.log("헤더에서 사용자 이름을 가져올 수 없음, 기본값 사용");
        return "사용자";

    } catch (e) {
        console.error("사용자 이름 가져오기 실패:", e);
        return "사용자";
    }
};


/**
 * 테스트 등록 팝업 열기
 */
scwin.openTestRegisterPopup = function() {
    // Test.xml과 동일한 방식으로 데이터 전달
    var taskData = {
        mode: "new",
        taskId: "",
        taskName: "",
        pjtId: scwin.CURRENT_PROJECT_ID,
        currentUserId: scwin.CURRENT_USER_ID
    };

    var jsnPopupData = {
        "type": "json",
        "name": "taskData",
        "data": taskData
    };

    var options = {
        id: "unit_test_popup",
        type: "wframePopup",
        width: "1400px",
        height: "900px",
        top: "50px",
        left: "100px",
        popupName: "단위테스트 케이스 등록",
        modal: true,
        closeAction: "scwin.testPopup_closeAction",
        dataObject: jsnPopupData  // 이 부분이 중요!
    };

    $p.openPopup("/InsWebApp/ui/test/UnitTestPopup.xml", options);
};

/**
 * 업무별 테스트 등록 팝업 열기
 */
scwin.openTestRegisterPopupWithTask = function(taskId, taskName) {
    console.log("업무별 테스트 등록 팝업 열기:", taskId, taskName);

    var currentUserId = scwin.CURRENT_USER_ID || "1";
    var currentUserName = scwin.getCurrentUserName();
    var currentProjectId = scwin.CURRENT_PROJECT_ID || "";

    var taskData = {
        mode: "new",
        taskId: taskId,
        taskName: taskName,
        pjtId: currentProjectId,
        currentUserId: currentUserId,
        currentUserName: currentUserName
    };

    var jsnPopupData = {
        "type": "json",
        "name": "taskData",
        "data": taskData
    };

    var options = {
        id: "unit_test_popup_with_task",
        type: "wframePopup",
        width: "1400px",
        height: "900px",
        top: "50px",
        left: "100px",
        popupName: "단위테스트 케이스 등록 (업무: " + taskName + ")",
        modal: true,
        closeAction: "scwin.testPopup_closeAction",
        dataObject: jsnPopupData
    };

    console.log("업무별 팝업 열기 - 사용자 정보 포함:", taskData);
    $p.openPopup("/InsWebApp/ui/test/UnitTestPopup.xml", options);
};

/**
 * 업무별 테스트 조회 팝업 열기
 */
scwin.openTestViewPopupWithTask = function(taskId, taskName) {
    console.log("업무별 테스트 조회 팝업 열기:", taskId, taskName);

    dmp_search.set("searchTaskId", taskId);

    if (scwin.CURRENT_PROJECT_ID && scwin.CURRENT_PROJECT_ID !== "") {
        scwin.searchUnitTestsByProject();
    } else {
        scwin.searchUnitTests();
    }

    setTimeout(function() {
        var successCount = dlt_successList.getTotalRow();
        var failCount = dlt_failList.getTotalRow();
        var totalCount = successCount + failCount;

        if (totalCount == 0) {
            var promise = $c.win.confirm(`업무 "${taskName}"에 등록된 테스트가 없습니다.\n\n새로운 테스트를 등록하시겠습니까?`);
            promise.then(function(result) {
                if (result) {
                    scwin.openTestRegisterPopupWithTask(taskId, taskName);
                }
            });
        }
    }, 500);
};

/**
 * 테스트 팝업 닫기 콜백
 */
scwin.testPopup_closeAction = function(e) {
    console.log("테스트 팝업 닫기 콜백");

    // 목록 새로고침
    if (scwin.CURRENT_PROJECT_ID && scwin.CURRENT_PROJECT_ID !== "") {
        scwin.searchUnitTestsByProject();
    } else {
        scwin.searchUnitTests();
    }

    return true;
};

/**
 * 일반 단위테스트 목록 조회
 */
scwin.searchUnitTests = function() {
    console.log("일반 단위테스트 목록 조회 시작");

    dmp_search.set("pageIndex", "1");
    dmp_search.set("pageSize", "1000");

    $c.sbm.execute($p, sbm_selectUnitTestList);
};

/**
 * 프로젝트별 단위테스트 목록 조회
 */
scwin.searchUnitTestsByProject = function() {
    if (!scwin.CURRENT_PROJECT_ID || scwin.CURRENT_PROJECT_ID === "") {
        console.log("프로젝트 ID가 없어 일반 조회를 실행합니다.");
        scwin.searchUnitTests();
        return;
    }

    console.log("프로젝트별 단위테스트 목록 조회 시작:", scwin.CURRENT_PROJECT_ID);

    dmp_search.set("pjtId", scwin.CURRENT_PROJECT_ID);
    dmp_search.set("pageIndex", "1");
    dmp_search.set("pageSize", "1000");

    $c.sbm.execute($p, sbm_selectUnitTestListByProject);
};

/**
 * 단위테스트 목록 조회 완료
 */
scwin.sbm_selectUnitTestList_submitdone = function(e) {
    console.log("단위테스트 목록 조회 완료", e);

    var elData = e.responseJSON.elData;
    var elHeader = e.responseJSON.elHeader;

    if (!elHeader || elHeader.resSuc == false) {
        $c.win.alert(`에러코드: ${elHeader.resCode}\n에러메시지: ${elHeader.resMsg}`);
        return false;
    }

    var allData = elData.unitTestList || [];
    var totalCount = elData.totalCount || 0;

    console.log("전체 데이터:", allData.length, "개");
    console.log("총 개수:", totalCount);

    scwin.globalElData = elData;
    scwin.processTestData(allData, totalCount);

    setTimeout(function() {
        scwin.setPriorityStyle();
        scwin.setTestTypeStyle();
    }, 100);
};

/**
 * 프로젝트별 단위테스트 목록 조회 완료
 */
scwin.sbm_selectUnitTestListByProject_submitdone = function(e) {
    console.log("프로젝트별 단위테스트 목록 조회 완료", e);

    try {
        var elData = e.responseJSON.elData;
        var elHeader = e.responseJSON.elHeader;

        if (!elHeader || elHeader.resSuc == false) {
            $c.win.alert(`에러코드: ${elHeader.resCode}\n에러메시지: ${elHeader.resMsg}`);
            return false;
        }

        var allData = elData.unitTestList || [];
        var totalCount = elData.totalCount || 0;

        scwin.globalElData = elData;

        console.log("프로젝트별 전체 데이터:", allData.length, "개");
        console.log("프로젝트별 총 개수:", totalCount);

        scwin.processTestData(allData, totalCount);

        setTimeout(function() {
            scwin.setPriorityStyle();
            scwin.setTestTypeStyle();
        }, 100);

    } catch (error) {
        console.error("프로젝트별 조회 완료 처리 중 오류:", error);
    }
};

/**
 * 테스트 데이터 처리
 */
scwin.processTestData = function(allData, totalCount) {
    console.log("=== 테스트 데이터 처리 시작 ===");
    console.log("원본 데이터 샘플:", allData.length > 0 ? allData[0] : "없음");

    var filteredData = allData;

    // 상태별 데이터 필터링
    var successData = [];
    var failData = [];

    for (var i = 0; i < filteredData.length; i++) {
        var item = filteredData[i];

        // 테스트 타입명, 우선순위명 추가
        item.testTypeName = scwin.getTestTypeName(item.testType);
        item.priorityName = scwin.getPriorityName(item.priority);

        // 실행일시 포맷팅 (YYYY-MM-DD HH:mm:ss → YYYY-MM-DD)
        if (item.executionDate) {
            // 날짜 포맷 정리 (시간 부분 제거)
            if (item.executionDate.length > 10) {
                item.executionDate = item.executionDate.substring(0, 10);
            }
        }

        // 소요시간 포맷팅 (분 단위로 표시)
        if (item.duration) {
            if (!item.duration.includes("분")) {
                item.duration = item.duration + "분";
            }
        }

        console.log("처리된 아이템 " + i + ":", {
            testCaseId: item.testCaseId,
            testStatus: item.testStatus,
            executionDate: item.executionDate,
            duration: item.duration,
            testTypeName: item.testTypeName,
            priorityName: item.priorityName
        });

        // 상태별 분류
        if (item.testStatus === "SUC") {
            successData.push(item);
        } else if (item.testStatus === "FAI") {
            failData.push(item);
        }
    }

    console.log("성공 데이터:", successData.length, "개");
    console.log("실패 데이터:", failData.length, "개");

    if (successData.length > 0) {
        console.log("성공 데이터 첫 번째 아이템:", successData[0]);
    }
    if (failData.length > 0) {
        console.log("실패 데이터 첫 번째 아이템:", failData[0]);
    }

    scwin.successPageInfo.data = successData;
    scwin.successPageInfo.totalCount = successData.length;
    scwin.failPageInfo.data = failData;
    scwin.failPageInfo.totalCount = failData.length;

    scwin.updateGridData();
    scwin.updateCountLabels(filteredData.length, successData.length, failData.length);
    scwin.updatePagination();

    console.log("=== 테스트 데이터 처리 완료 ===");
};

/**
 * 그리드 데이터 업데이트
 */
scwin.updateGridData = function() {
    console.log("그리드 데이터 업데이트 시작");

    try {
        var successPageData = scwin.getPageData(scwin.successPageInfo.data, scwin.successPageInfo);
        var failPageData = scwin.getPageData(scwin.failPageInfo.data, scwin.failPageInfo);

        console.log("성공 그리드 업데이트 데이터:", successPageData);
        console.log("실패 그리드 업데이트 데이터:", failPageData);

        if (successPageData.length > 0) {
            console.log("성공 첫 번째 데이터 상세:", {
                testCaseId: successPageData[0].testCaseId,
                executionDate: successPageData[0].executionDate,
                duration: successPageData[0].duration,
                assigneeName: successPageData[0].assigneeName
            });
        }

        dlt_successList.setJSON(successPageData);
        dlt_failList.setJSON(failPageData);

        console.log("그리드 설정 후 성공 리스트 총 행 수:", dlt_successList.getTotalRow());
        console.log("그리드 설정 후 실패 리스트 총 행 수:", dlt_failList.getTotalRow());

        // 그리드 데이터 설정 후 확인
        if (dlt_successList.getTotalRow() > 0) {
            console.log("성공 그리드 첫 번째 행 데이터:", dlt_successList.getRowJSON(0));
        }

        console.log("그리드 데이터 업데이트 완료");

        setTimeout(function() {
            scwin.setPriorityStyle();
            scwin.setTestTypeStyle();
        }, 50);

    } catch (err) {
        console.error("그리드 데이터 업데이트 오류:", err);
    }
};

/**
 * 페이지별 데이터 추출
 */
scwin.getPageData = function(data, pageInfo) {
    if (!data || !pageInfo) {
        return [];
    }

    var startIndex = (pageInfo.currentPage - 1) * pageInfo.pageSize;
    var endIndex = startIndex + pageInfo.pageSize;
    return data.slice(startIndex, endIndex);
};

/**
 * 카운트 라벨 업데이트
 */
scwin.updateCountLabels = function(total, success, fail) {
    try {
        spn_successListCnt.setLabel(success);
        spn_failListCnt.setLabel(fail);
    } catch (e) {
        console.error("카운트 라벨 업데이트 오류:", e);
    }
};

/**
 * 페이징 업데이트
 */
scwin.updatePagination = function() {
    try {
        scwin.updateStatePagination(scwin.successPageInfo, pgl_success);
        scwin.updateStatePagination(scwin.failPageInfo, pgl_fail);
    } catch (e) {
        console.error("페이징 업데이트 오류:", e);
    }
};

/**
 * 상태별 페이징 업데이트
 */
scwin.updateStatePagination = function(pageInfo, paginationComponent) {
    try {
        var totalPages = Math.ceil(pageInfo.totalCount / pageInfo.pageSize);
        console.log("페이징 업데이트:", pageInfo.totalCount, pageInfo.pageSize, totalPages);

        if (totalPages > 0) {
            paginationComponent.setCount(totalPages);
            paginationComponent.setSelectedIndex(pageInfo.currentPage);
        } else {
            paginationComponent.setCount(0);
        }
    } catch (e) {
        console.error("상태별 페이징 업데이트 오류:", e);
    }
};

/**
 * 성공 그리드 더블클릭
 */
scwin.success_grd_oncelldblclick = function(row, col, colId) {
    console.log("성공그리드 더블클릭 - 행:", row);

    if (row < 0 || row >= dlt_successList.getTotalRow()) {
        console.error("유효하지 않은 행 번호:", row);
        return;
    }

    var selectedData = dlt_successList.getRowJSON(row);
    console.log("선택된 성공 데이터 전체:", selectedData);

    if (!selectedData || !selectedData.testCaseId) {
        console.error("테스트케이스ID가 없습니다:", selectedData);
        $c.win.alert("유효하지 않은 데이터입니다.");
        return;
    }

    console.log("팝업으로 전달할 데이터 요약:", {
        testCaseId: selectedData.testCaseId,
        testCaseName: selectedData.testCaseName,
        taskName: selectedData.taskName,
        testStatus: selectedData.testStatus
    });

    scwin.showDetailPopup(selectedData);
};

/**
 * 실패 그리드 더블클릭
 */
scwin.fail_grd_oncelldblclick = function(row, col, colId) {
    console.log("실패그리드 더블클릭 - 행:", row);

    if (row < 0 || row >= dlt_failList.getTotalRow()) {
        console.error("유효하지 않은 행 번호:", row);
        return;
    }

    var selectedData = dlt_failList.getRowJSON(row);
    console.log("선택된 실패 데이터 전체:", selectedData);

    if (!selectedData || !selectedData.testCaseId) {
        console.error("테스트케이스ID가 없습니다:", selectedData);
        $c.win.alert("유효하지 않은 데이터입니다.");
        return;
    }

    console.log("팝업으로 전달할 데이터 요약:", {
        testCaseId: selectedData.testCaseId,
        testCaseName: selectedData.testCaseName,
        taskName: selectedData.taskName,
        testStatus: selectedData.testStatus
    });

    scwin.showDetailPopup(selectedData);
};

/**
 * 상세보기 팝업 표시
 */
scwin.showDetailPopup = function(selectedData) {
    console.log("상세보기 팝업 표시:", selectedData);

    if (!selectedData || !selectedData.testCaseId) {
        $c.win.alert("유효하지 않은 데이터입니다.");
        return;
    }

    // Test.xml과 완전히 동일한 방식으로 데이터 구성
    var detailData = {
        mode: "view",
        testData: selectedData, // 전체 데이터를 직접 전달
        pjtId: scwin.CURRENT_PROJECT_ID,
        currentUserId: scwin.CURRENT_USER_ID
    };

    console.log("팝업으로 전달할 데이터:", detailData);

    // 데이터 전달을 위한 다중 방법 적용
    // 방법 1: 표준 dataObject 방식
    var jsnPopupData = {
        "type": "json",
        "name": "detailData",
        "data": detailData
    };

    // 방법 2: 부모 창에 임시 저장 (대안)
    try {
        window.tempPopupData = { detailData: detailData };
        console.log("임시 데이터 저장:", window.tempPopupData);
    } catch(e) {
        console.log("임시 데이터 저장 실패:", e);
    }

    var options = {
        id: "unit_test_detail_popup",
        type: "wframePopup",
        width: "1400px",
        height: "900px",
        top: "50px",
        left: "100px",
        popupName: "단위테스트 케이스 상세정보",
        modal: true,
        closeAction: "scwin.testPopup_closeAction",
        dataObject: jsnPopupData
    };

    $p.openPopup("/InsWebApp/ui/test/UnitTestPopup.xml", options);
};



