 */
scwin.sbm_selectUnitTestStatistics_submitdone = function(e) {
    console.log("통계 조회 완료", e);

    var elData = e.responseJSON.elData;
    var elHeader = e.responseJSON.elHeader;

    if (!elHeader || elHeader.resSuc == false) {
        console.error("통계 조회 실패:", elHeader ? elHeader.resMsg : "알 수 없는 오류");
        return;
    }

    dmp_statistics.setJSON(elData);
    console.log("통계 정보:", elData);
};

